/**
 * Shared variable handling logic for workflow designers (v2 and advanced).
 *
 * Handles:
 * - Variable initialization into workflowModel
 * - Variable data preparation for saving
 * - Script_data encryption for DocOperator cards
 * - List variable serialization (comma-separated)
 */

import { notify } from 'src/components/notifications/notify';
import { uid } from 'quasar';
import { CONSTANTS } from 'src/constants';
import { encodeData } from 'src/utils/cryptoStorage';
import { isUndefinedOrNull } from 'src/utils/general';
import { i18n } from 'src/boot/i18n';
import { componentReference, defaultComponentName } from './work-flow-builder.js';

/**
 * Detects whether a value is an AES-GCM encrypted blob produced by encodeData().
 * Encrypted values are JSON strings containing iv, encryptedData, and tag fields.
 */
export function isEncryptedValue(value: any): boolean {
  if (typeof value !== 'string') return false;
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === 'object'
      && 'iv' in parsed && 'encryptedData' in parsed && 'tag' in parsed;
  } catch {
    return false;
  }
}

/**
 * Populate docOperator tracking maps from saved card data when a UUID
 * has no existing entry (e.g. after UUIDs are re-assigned during load).
 * Detects encrypted values and marks them as locked/sensitive.
 */
export function populateDocOperatorFromSavedData(
  savedData: Record<string, any>,
  uuid: string,
  docOperatorVariables: Record<string, any>,
  docOperatorLockedSensitiveData: Record<string, string[]>,
  docOperatorVariablesSensitive: Record<string, string[]>,
): void {
  docOperatorVariables[uuid] = { ...savedData };

  if (!docOperatorLockedSensitiveData[uuid]) {
    docOperatorLockedSensitiveData[uuid] = [];
  }
  if (!docOperatorVariablesSensitive[uuid]) {
    docOperatorVariablesSensitive[uuid] = [];
  }

  for (const [key, val] of Object.entries(savedData)) {
    if (isEncryptedValue(val)) {
      if (!docOperatorLockedSensitiveData[uuid].includes(key)) {
        docOperatorLockedSensitiveData[uuid].push(key);
      }
      if (!docOperatorVariablesSensitive[uuid].includes(key)) {
        docOperatorVariablesSensitive[uuid].push(key);
      }
    }
  }
}

/**
 * Restore docOperator state (variables, sensitive, locked) from a source
 * snapshot into a new UUID. Used during copy-paste and duplicate operations.
 */
export function restoreDocOperatorState(
  source: { variables: any; sensitive?: string[]; locked?: string[] },
  newUuid: string,
  docOperatorVariables: Record<string, any>,
  docOperatorVariablesSensitive: Record<string, string[]>,
  docOperatorLockedSensitiveData: Record<string, string[]>,
): void {
  docOperatorVariables[newUuid] = JSON.parse(JSON.stringify(source.variables));
  if (source.sensitive?.length) {
    docOperatorVariablesSensitive[newUuid] = [...source.sensitive];
  }
  if (source.locked?.length) {
    docOperatorLockedSensitiveData[newUuid] = [...source.locked];
  }
}

/**
 * Maps a variable display_name to the appropriate component reference name.
 * Returns the display_name if it's a known component reference, otherwise the default component.
 */
export function getComponentName(display_name: string): string {
  return componentReference.includes(display_name) ? display_name : defaultComponentName;
}

/**
 * Whether a variable's badge label resolves from a dropdown list (its component
 * exposes `updateModelOnLoad`). Such badges must re-resolve when their lazily
 * loaded list arrives. `componentRef` is badge.vue's display_name -> component map.
 */
export function badgeResolvesFromDropdownList(
  displayName: string | undefined,
  componentRef: Record<string, any>,
): boolean {
  return !!(displayName && componentRef[displayName]?.methods?.updateModelOnLoad);
}

/**
 * Resolves a workflow-variable reference token (`wf_var.{id}` / `{id}`) against
 * the current workflow variables list, returning the matched variable or null.
 */
export function resolveWorkflowVariableRef(
  data: string | null | undefined,
  workflowVariables?: Array<{ id: string; name: string }> | null,
): { id: string; name: string } | null {
  if (!data || typeof data !== 'string' || !workflowVariables?.length) return null;
  const token = data.startsWith('wf_var.') ? data.slice(7) : data;
  return workflowVariables.find((v) => v.id === token) ?? null;
}

/**
 * Initializes a variable into the workflowModel.
 *
 * @param workflowModel - The workflow model object (reactive)
 * @param variable - The variable to initialize
 * @param isDefaultElement - If true, initializes with default/empty values. If false, loads from variable.data
 * @param docOperatorVariables - DocOperator variables (for operator type)
 */
export function initWorkFlowMode(
  workflowModel: any,
  variable: any,
  isDefaultElement: boolean,
  docOperatorVariables?: any
) {
  if (!variable?.uuid) return;
  // Determine badgeValue: prefer a pre-resolved badgeValue from processCardVariablesForLoad
  // (e.g. label for 'script', display_name for 'script_data'), then fall back to data or display_name.
  // script/script_data badges must never show raw IDs or encrypted JSON — always use display_name as fallback.
  const scriptVarNames = ['script', 'script_data'];
  const isScriptVar = scriptVarNames.includes(variable.display_name);
  let badgeValue = variable.display_name;
  if (variable.badgeValue) {
    badgeValue = variable.badgeValue;
  } else if (variable.data && !isScriptVar) {
    badgeValue = variable.data;
  }
  workflowModel[variable.uuid] = {
    value: variable.data ? variable.data : '',
    badgeValue,
    defaultValue: variable.display_name,
    dependency_variables: variable.dependency_variables ? variable.dependency_variables : null,
    is_list: variable.is_list,
  };

  if (isDefaultElement) {
    if (variable.data_type == CONSTANTS.operator && variable.data) {
      workflowModel[variable.uuid].value = variable.data;
    }
    return;
  }

  if (variable.is_list) {
    if (variable.data) {
      workflowModel[variable.uuid].value = variable.data.split(',');
    }
  } else {
    workflowModel[variable.uuid].value = variable.data;
  }

  // Ensure badgeValue is never empty - always fallback to defaultValue
  if (!workflowModel[variable.uuid].badgeValue || workflowModel[variable.uuid].badgeValue === '') {
    workflowModel[variable.uuid].badgeValue = variable.display_name;
  }
}

/**
 * Initializes all variables on a card: assigns UUID, componentName,
 * and registers in the workflowModel.
 *
 * @param variables - The card's variables array (mutated in-place)
 * @param workflowModel - The reactive workflow model
 * @param getComponentName - Function mapping display_name -> component name
 * @param options.preserveExistingUuids - If true, only assign uuid when missing (for auto-save restore)
 */
export function initializeCardVariables(
  variables: any[],
  workflowModel: any,
  getComponentName: (displayName: string) => string,
  options?: { preserveExistingUuids?: boolean },
): void {
  if (!variables?.length) return;

  for (const variable of variables) {
    if (options?.preserveExistingUuids) {
      if (!variable.uuid) variable.uuid = uid();
    } else {
      variable.uuid = uid();
    }
    variable.componentName = getComponentName(variable.display_name);
    initWorkFlowMode(workflowModel, variable, true);
  }
}

/**
 * Prepares variable data for saving by reading from workflowModel.
 *
 * @param workflowModel - The workflow model object
 * @param variable - The variable to process
 * @param docOperatorVariables - DocOperator variables
 * @param docOperatorVariablesSensitive - Sensitive variable tracking
 * @param docOperatorLockedSensitiveData - Locked sensitive data tracking
 * @returns The variable data as a string
 */
export async function prepareVariableData(
  workflowModel: any,
  variable: any,
  docOperatorVariables?: any,
  docOperatorVariablesSensitive?: any,
  docOperatorLockedSensitiveData?: any
): Promise<string> {
  try {
    if (!variable.uuid || !workflowModel[variable.uuid]) {
      return '';
    }

    const dataValue = workflowModel[variable.uuid].value;
    let data = '';

    if (variable.is_list && dataValue) {
      data = Array.isArray(dataValue)
        ? dataValue.join(',')
        : dataValue.toString();
    } else {
      // Handle script_data with encryption (for DocOperator cards)
      if ([variable.display_name, variable.defaultValue].includes('script_data')) {
        if (docOperatorVariables && docOperatorVariables[variable.uuid]) {
          for (const key of Object.keys(docOperatorVariables[variable.uuid])) {
            const val = docOperatorVariables[variable.uuid][key];
            if (
              val
              && docOperatorVariablesSensitive?.[variable.uuid]?.includes(key)
              && (
                !docOperatorLockedSensitiveData?.[variable.uuid]
                || !docOperatorLockedSensitiveData[variable.uuid].includes(key)
              )
              && !isEncryptedValue(val)
            ) {
              const encoded_data = await encodeData(val);
              if (!encoded_data) {
                notify.error(i18n.global.t('wf_error_encrypting_data'));
                return '';
              }
              docOperatorVariables[variable.uuid][key] = encoded_data;
              if (isUndefinedOrNull(docOperatorLockedSensitiveData[variable.uuid])) {
                docOperatorLockedSensitiveData[variable.uuid] = [] as string[];
              }
              docOperatorLockedSensitiveData[variable.uuid].push(key);
            }
          }
          return JSON.stringify(docOperatorVariables[variable.uuid]);
        }
      }
      data = dataValue ? dataValue.toString() : '';
    }

    return data;
  } catch (err) {
    console.error('Error preparing variable data:', err);
    return '';
  }
}

/**
 * Merge template variable metadata (id, display_name, data_set) into saved card variables.
 *
 * Saved workflows may store variables in a different order than the card
 * template defines them. Matching by id/display_name/data_type (not array index)
 * ensures each saved variable gets the correct template metadata.
 *
 * Priority: id match > display_name match > data_type match.
 * Also restores display_name from the template when the DB value is null,
 * which is required for badge rendering (badge.vue checks display_name).
 */
export function mergeTemplateVariableMetadata(
  savedVariables: Array<{ id?: string; display_name?: string; data_type?: string; data_set?: any[] }>,
  templateVariables: Array<{ id: string; display_name: string; data_type?: string; data_set?: any[] }>,
): void {
  for (const savedVar of savedVariables) {
    const templateVar = templateVariables.find(
      (tv) => tv.id === savedVar.id
        || tv.display_name === savedVar.display_name
        || tv.data_type === savedVar.data_type,
    );
    if (!templateVar) continue;
    savedVar.id = templateVar.id;
    if (!savedVar.display_name && templateVar.display_name) {
      savedVar.display_name = templateVar.display_name;
    }
    if (!savedVar.data_set && templateVar.data_set) {
      savedVar.data_set = templateVar.data_set;
    }
  }
}

/**
 * Processes variables when loading a card (handles script_data, UUIDs, etc).
 *
 * @param card - The card containing variables
 * @param docOperatorVariables - DocOperator variables
 * @param docOperatorLockedSensitiveData - Locked sensitive data tracking
 * @param setDocOperatorVariables - Function to set DocOperator variables
 * @param doc_operator_prompts - DocOperator prompts list
 * @param getComponentName - Function to get component name from display_name
 * @param workflowModel - The workflow model object
 */
export function processCardVariablesForLoad(
  card: any,
  docOperatorVariables: any,
  docOperatorLockedSensitiveData: any,
  setDocOperatorVariables: any,
  doc_operator_prompts: any,
  getComponentName: (display_name: string) => string,
  workflowModel: any,
  docOperatorVariablesSensitive?: any,
) {
  if (!card.variables) return;

  // First pass: Assign UUIDs and detect script variables
  let script_vars = false;
  for (let variable of card.variables) {
    variable.uuid = uid();
    if (variable.display_name == 'script') {
      script_vars = true;
    }
  }

  // Special handling for script_data (DocOperator encryption)
  // Two-pass approach: first collect all data, then call setDocOperatorVariables
  // only when there's no saved script_data (to avoid wiping loaded values).
  if (script_vars) {
    let script_var_index = null;
    let script_var_data = null;
    let script_var_uuid: string | null = null;
    let script_data_var_index = null;
    let script_data_var_uuid: string | null = null;
    let hasSavedScriptData = false;
    let matchedPrompt: any = null;

    // Pass 1: Parse script_data and identify the script prompt
    let index = 0;
    for (let variable of card.variables) {
      if (variable.display_name == 'script_data' && variable.data) {
        script_data_var_index = index;
        script_data_var_uuid = variable.uuid;
        variable.badgeValue = variable.display_name;
        try {
          docOperatorVariables[variable.uuid] = JSON.parse(variable.data);
          hasSavedScriptData = Object.keys(docOperatorVariables[variable.uuid]).length > 0;
        } catch {
          console.error('Failed to parse script_data for variable:', variable.uuid);
          docOperatorVariables[variable.uuid] = {};
        }
      } else if (variable.display_name == 'script' && variable.data) {
        script_var_index = index;
        script_var_data = variable.data;
        script_var_uuid = variable.uuid;
        for (const operator_prompt of doc_operator_prompts) {
          if (variable.data == operator_prompt.value) {
            matchedPrompt = operator_prompt;
            variable.badgeValue = operator_prompt.label;
            break;
          }
        }
      }
      index += 1;
    }

    // Pass 2: Only call setDocOperatorVariables when there's no saved script_data.
    // When script_data has saved values, calling setDocOperatorVariables would
    // wipe the loaded values with empty template strings.
    if (matchedPrompt && script_var_uuid) {
      if (!hasSavedScriptData) {
        setDocOperatorVariables(matchedPrompt, script_var_uuid);
      }
    }

    // Set locked sensitive data and sensitive variable list for encryption tracking
    if (script_data_var_index != null && script_var_index != null && matchedPrompt) {
      if (!docOperatorLockedSensitiveData[script_data_var_uuid!]) {
        docOperatorLockedSensitiveData[script_data_var_uuid!] = matchedPrompt.sensitive_variables ? matchedPrompt.sensitive_variables.slice() : [];
      }
      // Set sensitive variables directly (store's setDocOperatorVariables
      // may not find the card in selectedThenCards during initial load)
      if (docOperatorVariablesSensitive && matchedPrompt.sensitive_variables) {
        docOperatorVariablesSensitive[script_data_var_uuid!] = matchedPrompt.sensitive_variables.slice();
      }
    }
  }

  // Final pass: Set component names and initialize workflow model
  for (let variable of card.variables) {
    variable.componentName = getComponentName(variable.display_name);
    initWorkFlowMode(workflowModel, variable, false);
  }
}

/**
 * Processes variables for saving (clones, prepares data, removes UUIDs).
 *
 * @param variables - Array of variables to process
 * @param workflowModel - The workflow model object
 * @param docOperatorVariables - DocOperator variables
 * @param docOperatorVariablesSensitive - Sensitive variable tracking
 * @param docOperatorLockedSensitiveData - Locked sensitive data tracking
 * @returns Promise resolving to processed variables array
 */
export async function processVariablesForSave(
  variables: any[],
  workflowModel: any,
  docOperatorVariables?: any,
  docOperatorVariablesSensitive?: any,
  docOperatorLockedSensitiveData?: any
): Promise<any[]> {
  if (!variables?.length) return [];
  return await Promise.all(
    variables.map(async (variable: any) => {
      const clonedVar = JSON.parse(JSON.stringify(variable));
      clonedVar.data = await prepareVariableData(
        workflowModel,
        variable,
        docOperatorVariables,
        docOperatorVariablesSensitive,
        docOperatorLockedSensitiveData
      );
      delete clonedVar.uuid;
      return clonedVar;
    })
  );
}
