import {
  workflowSplitDelimiter,
  workflowTranslationDelimiter,
  invalid,
} from 'src/constants';
import { dynamicObj } from '../assets';
import { i18n } from 'src/boot/i18n';
import { storeToRefs } from 'pinia';
import { useWorkflowBuilderStore, useDropdownStore } from 'src/store/main';

/**
 * Resolve a partner-card translation field (e.g. title_formatted, description)
 * that may be either a plain string or a locale object like {"en":"…","de":"…"}.
 * Returns the best match for the current app language, falling back to 'en'.
 */
export function translateField(
  value: string | Record<string, string> | null | undefined,
): string {
  if (!value) return '';
  if (typeof value === 'object') {
    const lang = (i18n.getLanguage?.() || 'en').split('-')[0];
    return value[lang] || value['en'] || Object.values(value)[0] || '';
  }
  return value;
}

/**
 * Get the best display text for a workflow card.
 * Partner cards carry title_formatted / description as locale objects;
 * built-in cards use a translation-key string in the text field.
 */
export function getCardDisplayText(card: dynamicObj): string {
  // Partner cards: prefer title_formatted (locale object), fall back to text
  if (card.is_partner_card && card.title_formatted) {
    return translateField(card.title_formatted);
  }
  // For built-in cards or partner cards without title_formatted, return raw text
  return card.text || '';
}

/**
 * Resolve the plain display text for a card ready for rendering.
 * If the raw text contains split-delimiter markers it is returned as-is
 * (the caller will render variable badges); otherwise it is passed through i18n.
 * Shared by AdvancedWorkflowCard, generic-card, and generic_card_logs.
 */
export function resolveCardPlainText(card: dynamicObj): string {
  const raw = getCardDisplayText(card);
  return raw.includes(workflowSplitDelimiter) ? raw : i18n.t(raw);
}

const workflow_builder_store = useWorkflowBuilderStore();
const {
  workflowModel,
  selectedWhenCards,
  selectedAndCards,
  selectedThenCards,
} = storeToRefs(workflow_builder_store);
const dropdown_store = useDropdownStore();
const { table_column_name_list } = storeToRefs(dropdown_store);

export function getVariableData(
  var_id: string,
  item: dynamicObj,
  data_for_vars: dynamicObj,
): string {
  for (const variable of item.variables) {
    if (
      variable.id.split(workflowSplitDelimiter).join('') ==
      var_id.split(workflowSplitDelimiter).join('')
    ) {
      switch (variable.display_name) {
        case 'user':
        case 'users':
        case 'groups':
        // case 'group_name':
        case 'decision_table':
        case 'script':
        case 'workflow':
        case 'workflows':
          return getVariableDataForID(
            variable.display_name,
            'id',
            variable.data,
            data_for_vars,
          ).replace(/,/g, ', ');

        case 'operator':
        case 'math_operator':
          return i18n.t(variable.data);

        case 'email_templates':
        case 'sub_org_id':
          return getVariableDataForID(
            variable.display_name,
            'value',
            variable.data,
            data_for_vars,
          ).replace(/,/g, ', ');
        case 'script_data':
          return variable.data.replace(/{/g, '').replace(/}/g, '') as string;
        default:
          break;
      }

      const var_split: string[] = variable.data.split(',');
      for (let i = 0; i < var_split.length; i++) {
        const var_transl: string =
          i18n.t(var_split[i], var_split[i]) != invalid
            ? i18n.t(var_split[i], var_split[i])
            : var_split[i];
        if (var_split[i] == var_transl) {
          var_split[i] =
            i18n.t(var_split[i].toLowerCase(), var_split[i]) != invalid
              ? i18n.t(var_split[i].toLowerCase(), var_split[i])
              : var_split[i];
        } else {
          var_split[i] = var_transl;
        }
      }
      return var_split.join(', ');
    }
  }
  return '';
}

export function getVariableDataForID(
  display_name: string,
  id_key: string,
  var_id: any,
  data_for_vars: dynamicObj,
): string {
  const keys = Object.keys(data_for_vars);
  let data_key = display_name;
  var_id = var_id.toString().trim()
  if (display_name == 'sub_org_id') {
    data_key = 'subOrgList';
  } else if (display_name == 'user') {
    data_key = 'users';
  } else if (display_name == 'decision_table') {
    data_key = 'decision_tables';
  } else if (display_name == 'script') {
    data_key = 'prompts';
  } else if (display_name == 'workflow') {
    data_key = 'workflows';
  }
  if (keys.includes(data_key)) {
    const return_list: any[] = [];
    const added_var_ids: any[] = [];
    for (const variable_id of var_id.split(',')) {
      for (const item of data_for_vars[data_key]) {
        if (
          item[id_key] == variable_id &&
          !added_var_ids.includes(variable_id)
        ) {
          added_var_ids.push(variable_id);
          switch (display_name) {
            case 'user':
            case 'users':
              const name = item.first_name + ' ' + item.last_name;
              if (return_list.indexOf(name) == -1) {
                return_list.push(name);
              }
              break;

            case 'groups':
            // case 'group_name':
            case 'workflow':
            case 'workflows':
            case 'decision_table':
              return_list.push(item.name);
              break;
            case 'sub_org_id':
            case 'email_templates':
              return_list.push(item.label);
              break;
            case 'script':
              return_list.push(item.prompt_name);
              break;
          }
        }
      }
    }
    if (return_list.length > 0) {
      return return_list.toString();
    } else {
      return var_id as string;
    }
  } else {
    return var_id as string;
  }
}

export function prepareData(card_item: dynamicObj): Array<string> {
  const dataArray: string[] = [];
  try {
    if (!card_item) return dataArray;

    // Partner cards may carry a title_formatted locale object; resolve it first.
    // Built-in cards use a translation key that i18n.t() resolves to text with markers.
    // Partner cards store the markers directly in card_item.text, but i18n.t() strips
    // them because vue-i18n interprets __%...% as message-format interpolation.
    const rawText = getCardDisplayText(card_item);
    const displayText = rawText.includes(workflowSplitDelimiter)
      ? rawText
      : i18n.t(rawText);

    if (displayText.includes(workflowSplitDelimiter)) {
      const splitAray = displayText.split(/(__%)/);

      for (let index = 0; index < splitAray.length; index++) {
        let itemValue = '';

        if (splitAray[index]) {
          if (splitAray[index] == workflowSplitDelimiter) {
            itemValue =
              splitAray[index] + splitAray[index + 1] + splitAray[index + 2];
            index = index + 2;
          } else {
            itemValue = splitAray[index];
          }
          dataArray.push(itemValue);
        }
      }
    }
  } catch (err) {
    logError(err);
  }
  return dataArray;
}

export function prepareCard(
  card_item: dynamicObj,
  data_for_vars: dynamicObj,
): string {
  const final_text: string[] = [];
  const dataArray: string[] = prepareData(card_item);
  if (!dataArray || dataArray.length < 1) {
    // For partner cards whose text contains raw __%uuid__% markers,
    // strip the markers to show clean display text
    const rawText = getCardDisplayText(card_item);
    if (rawText.includes(workflowSplitDelimiter)) {
      return rawText.replace(/__%[0-9a-fA-F-]+__%/g, '').replace(/\s+/g, ' ').trim();
    }
    return i18n.t(rawText);
  }
  for (const str of dataArray) {
    if (str.startsWith(workflowSplitDelimiter)) {
      final_text.push(getVariableData(str, card_item, data_for_vars));
    } else if (str.startsWith(workflowTranslationDelimiter)) {
      final_text.push(i18n.t(str));
    } else {
      const str_translated = i18n.t(str);
      final_text.push(str_translated == invalid ? str : str_translated);
    }
  }
  if (final_text.length > 0) {
    return final_text.join(' ');
  }
  return '';
}

export function resetDependencyVariables(
  changed_component: string,
  new_value: string,
): boolean {
  let reset_dependency_variables = false;
  try {
    main_loop_workflowModel: for (const variable_uuid in workflowModel.value) {
      if (
        workflowModel.value[variable_uuid].dependency_variables &&
        workflowModel.value[variable_uuid].dependency_variables.includes(
          changed_component,
        )
      ) {
        switch (workflowModel.value[variable_uuid].defaultValue) {
          case 'table_column_name':
          case 'table_column_name_compare':
          case 'table_column_name_compare_to':
          case 'table_column_name_dependency':
          case 'table_column_name_left':
          case 'table_column_name_right':
            for (const column_entry of table_column_name_list.value) {
              if (column_entry.tables.indexOf(new_value) > -1) {
                continue main_loop_workflowModel;
              }
            }
            break;

          default:
            break;
        }
        workflowModel.value[variable_uuid].badgeValue =
          workflowModel.value[variable_uuid].defaultValue;
        workflowModel.value[variable_uuid].value = '';
        reset_dependency_variables = true;
        resetDependencyVariablesOnSelectedCards(variable_uuid);
      }

      if (
        workflowModel.value[variable_uuid].defaultValue == 'table_name' &&
        changed_component == 'table_name'
      ) {
        workflowModel.value[variable_uuid].badgeValue = i18n.t(new_value);
        workflowModel.value[variable_uuid].value = new_value;
      }
    }
  } catch (err) {
    logError(err);
  }
  return reset_dependency_variables;
}

function resetDependencyVariablesOnSelectedCards(variable_uuid: string) {
  if (selectedWhenCards.value) {
    for (const variable in selectedWhenCards.value.variables) {
      if (selectedWhenCards.value.variables[variable].uuid == variable_uuid) {
        selectedWhenCards.value.variables[variable].data = '';
        return;
      }
    }
  }
  if (selectedAndCards.value) {
    for (const and_card in selectedAndCards.value) {
      for (const variable in selectedAndCards.value[and_card].variables) {
        if (
          selectedAndCards.value[and_card].variables[variable].uuid ==
          variable_uuid
        ) {
          selectedAndCards.value[and_card].variables[variable].data = '';
          return;
        }
      }
    }
  }
  if (selectedThenCards.value) {
    for (const then_card in selectedThenCards.value) {
      for (const variable in selectedThenCards.value[then_card].variables) {
        if (
          selectedThenCards.value[then_card].variables[variable].uuid ==
          variable_uuid
        ) {
          selectedThenCards.value[then_card].variables[variable].data = '';
          return;
        }
      }
    }
  }
}

export function getVariableValueFromOtherVariableUUID(
  search_var_display_name: string,
  other_var_uuid: string,
): string | any[string] {
  let searched_var_uuid = '';
  if (selectedWhenCards.value) {
    main_loop_when: for (const variable in selectedWhenCards.value.variables) {
      if (selectedWhenCards.value.variables[variable].uuid == other_var_uuid) {
        for (const search_var in selectedWhenCards.value.variables) {
          if (
            selectedWhenCards.value.variables[search_var].display_name ==
            search_var_display_name
          ) {
            searched_var_uuid =
              selectedWhenCards.value.variables[search_var].uuid;
            break main_loop_when;
          }
        }
      }
    }
  }
  if (selectedAndCards.value && searched_var_uuid == '') {
    searched_var_uuid = searchCardsForUUID(
      selectedAndCards,
      search_var_display_name,
      other_var_uuid,
    );
  }
  if (selectedThenCards.value && searched_var_uuid == '') {
    searched_var_uuid = searchCardsForUUID(
      selectedThenCards,
      search_var_display_name,
      other_var_uuid,
    );
  }
  if (searched_var_uuid) {
    return workflowModel.value[searched_var_uuid].value;
  }
  return '';
}

function searchCardsForUUID(
  selectedCards: any,
  search_var_display_name: string,
  other_var_uuid: string,
): string {
  let searched_var_uuid = '';
  main_loop: for (const search_card in selectedCards.value) {
    for (const variable in selectedCards.value[search_card].variables) {
      if (
        selectedCards.value[search_card].variables[variable].uuid ==
        other_var_uuid
      ) {
        for (const search_var in selectedCards.value[search_card].value
          .variables) {
          if (
            selectedCards.value[search_card].value.variables[search_var]
              .display_name == search_var_display_name
          ) {
            searched_var_uuid =
              selectedCards.value[search_card].value.variables[search_var].uuid;
            break main_loop;
          }
        }
      }
    }
  }
  return searched_var_uuid;
}
